package com.mobileagent;
import android.app.DownloadManager;
import android.content.*;
import android.database.Cursor;
import android.net.Uri;
import java.io.*;
import java.net.*;
import java.util.*;
import org.json.*;

public final class Models {
 final Context context;final DownloadManager dm;final android.content.SharedPreferences prefs;
 public Models(Context c){context=c.getApplicationContext();dm=(DownloadManager)c.getSystemService(Context.DOWNLOAD_SERVICE);prefs=c.getSharedPreferences("downloads",0);folder().mkdirs();}
 public File folder(){return new File(context.getExternalFilesDir(null),"models");}
 public static Uri url(String text){Uri u=Uri.parse(text.trim());if(!"https".equals(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null)throw new IllegalArgumentException("Use a public HTTPS GGUF download URL.");if(u.getHost().equals("github.com")&&u.getPath()!=null&&u.getPath().contains("/blob/"))u=Uri.parse(text.trim().replace("github.com/","raw.githubusercontent.com/").replace("/blob/","/"));return u;}
 public long download(String link){Uri uri=url(link);String name=uri.getLastPathSegment();if(name==null||!name.toLowerCase(Locale.ROOT).endsWith(".gguf")||name.contains("\\")||name.contains("/")||name.equals(".gguf"))throw new IllegalArgumentException("Choose a single .gguf file URL.");if(new File(folder(),name).exists())throw new IllegalArgumentException("A file with this name already exists. Delete it before downloading again.");for(String v:prefs.getAll().values().stream().map(Object::toString).toArray(String[]::new))if(v.equals(name))throw new IllegalArgumentException("This download is already tracked.");
  long id=dm.enqueue(new DownloadManager.Request(uri).setTitle(name).setDescription("My Mobile Agent model").setAllowedOverMetered(true).setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED).setDestinationUri(Uri.fromFile(new File(folder(),name))));prefs.edit().putString(Long.toString(id),name).apply();return id;}
 public List<String[]> downloads(){List<String[]> out=new ArrayList<>();for(String key:prefs.getAll().keySet()){long id=Long.parseLong(key);try(Cursor c=dm.query(new DownloadManager.Query().setFilterById(id))){if(!c.moveToFirst()){prefs.edit().remove(key).apply();continue;}int state=c.getInt(c.getColumnIndexOrThrow(DownloadManager.COLUMN_STATUS));long done=c.getLong(c.getColumnIndexOrThrow(DownloadManager.COLUMN_BYTES_DOWNLOADED_SO_FAR)),total=c.getLong(c.getColumnIndexOrThrow(DownloadManager.COLUMN_TOTAL_SIZE_BYTES));String label=state==DownloadManager.STATUS_SUCCESSFUL?"Complete":state==DownloadManager.STATUS_FAILED?"Failed · reason "+c.getInt(c.getColumnIndexOrThrow(DownloadManager.COLUMN_REASON)):state==DownloadManager.STATUS_PAUSED?"Paused · waiting for network/storage":state==DownloadManager.STATUS_PENDING?"Queued":"Downloading";out.add(new String[]{key,prefs.getString(key,"model"),label,Long.toString(done),Long.toString(total),Integer.toString(state)});}}return out;}
 public void remove(long id){dm.remove(id);prefs.edit().remove(Long.toString(id)).apply();}
 public boolean complete(File f){for(String[] d:downloads())if(d[1].equals(f.getName()))return Integer.parseInt(d[5])==DownloadManager.STATUS_SUCCESSFUL;return true;}
 public List<File> files(){File[] list=folder().listFiles((dir,n)->n.toLowerCase(Locale.ROOT).endsWith(".gguf"));List<File> out=new ArrayList<>();if(list!=null)for(File f:list)if(complete(f))out.add(f);out.sort(Comparator.comparing(File::getName));return out;}
 public static void validate(File f)throws IOException{try(DataInputStream in=new DataInputStream(new FileInputStream(f))){if(in.readInt()!=0x47475546)throw new IOException("Invalid GGUF header. This may be an HTML page or a Git LFS pointer, not the model bytes.");if(f.length()<1024)throw new IOException("The model is incomplete.");}}
 public static List<String[]> github(String repo)throws Exception{if(!repo.matches("[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+"))throw new IllegalArgumentException("Enter GitHub owner/repository.");List<String[]> out=new ArrayList<>();HttpURLConnection c=(HttpURLConnection)new URL("https://api.github.com/repos/"+repo+"/releases?per_page=30").openConnection();c.setConnectTimeout(20000);c.setReadTimeout(30000);c.setRequestProperty("Accept","application/vnd.github+json");c.setRequestProperty("User-Agent","MyMobileAgent/1.0");try{if(c.getResponseCode()!=200)throw new IOException("GitHub returned "+c.getResponseCode()+". Check repository name or API rate limit; direct URLs also work.");ByteArrayOutputStream b=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){b.write(buf,0,n);if(b.size()>8*1024*1024)throw new IOException("Release listing too large.");}}JSONArray releases=new JSONArray(b.toString("UTF-8"));for(int i=0;i<releases.length();i++){JSONArray assets=releases.getJSONObject(i).getJSONArray("assets");for(int j=0;j<assets.length();j++){JSONObject a=assets.getJSONObject(j);if(a.getString("name").toLowerCase(Locale.ROOT).endsWith(".gguf"))out.add(new String[]{a.getString("name"),a.getString("browser_download_url"),Long.toString(a.optLong("size"))});}}return out;}finally{c.disconnect();}}
}
